      --radius-md: 12px;
      --focus: #d5e2ff;
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      margin: 0;
      min-height: 100%;
      background:
        radial-gradient(circle at top, #17213a 0%, var(--bg) 55%),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    body {
      min-height: 100vh;
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1000;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #08101d;
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 3rem 1.25rem;
    }

    .shell {
      width: min(100%, 760px);
      padding: 1.25rem;
    }

    .hero {
      display: grid;
      gap: 1rem;
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      background: linear-gradient(180deg, rgba(23, 34, 56, 0.98), rgba(15, 22, 39, 0.98));
      box-shadow: var(--shadow);
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lede {
      margin: 0;
      color: var(--muted);
      max-width: 60ch;
      overflow-wrap: anywhere;
    }

    .preview {
      display: grid;
      gap: 1rem;
      padding: 1rem;
      border-radius: var(--radius-lg);
      background: var(--panel);
      border: 1px solid var(--border);
    }

    .preview-media {
      margin: 0;
      overflow: hidden;
      border-radius: calc(var(--radius-lg) - 4px);
      border: 1px solid #2d3951;
      background: #0f1728;
    }

    .preview-media img {
      display: block;
      width: 100%;
      height: auto;
      max-width: 100%;
    }

    .preview-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem 1rem;
      align-items: center;
      justify-content: space-between;
    }

    .details {
      display: grid;
      gap: 0.2rem;
      min-width: 0;
    }

    .details strong {
      font-size: 1rem;
    }

    .details span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      font: inherit;
      font-weight: 600;
      line-height: 1;
      padding: 0.85rem 1.15rem;
      color: var(--text);
      background: var(--panel-elevated);
      cursor: pointer;
      transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
    }

    button:hover {
      transform: translateY(-1px);
      border-color: #39507c;
    }

    button:active {
      transform: translateY(0);
    }

    .trigger {
      background: linear-gradient(180deg, #d05656, #b73f3f);
      color: #fff7f7;
      border-color: #d96e6e;
    }

    .trigger:hover {
      border-color: #ff9191;
      background: linear-gradient(180deg, #e06262, #c54848);
    }

    .secondary {
      background: transparent;
      border-color: #3a4761;
      color: var(--text);
    }

    button:focus-visible,
    a:focus-visible,
    dialog button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .dialog {
      width: min(100%, 520px);
      margin: auto;
      padding: 0;
      border: 1px solid #33415f;
      border-radius: 28px;
      background: linear-gradient(180deg, #151d2f, #101726);
      color: var(--text);
      box-shadow: 0 40px 90px rgba(0, 0, 0, 0.62);
    }

    .dialog::backdrop {
      background: rgba(4, 8, 16, 0.72);
      backdrop-filter: blur(4px);
    }

    .dialog-panel {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
    }

    .dialog-header {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 1rem;
    }

    .dialog-title {
      margin: 0;
      font-size: 1.35rem;
      line-height: 1.2;
    }

    .close {
      flex: none;
      width: 2.5rem;
      height: 2.5rem;
      padding: 0;
      border-radius: 999px;
      border-color: #3a4761;
      background: transparent;
    }

    .dialog-body {
      margin: 0;
      color: var(--muted);
      overflow-wrap: anywhere;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      justify-content: flex-end;
    }

    .destructive {
      background: linear-gradient(180deg, #df6464, #c24343);
      border-color: #ef8787;
      color: #fff;
    }

    .destructive:hover {
      border-color: #ffd0d0;
      background: linear-gradient(180deg, #ea7070, #d04c4c);
    }

    .status {
      min-height: 1.5rem;
      color: #b8ffcf;
      font-weight: 600;
    }

    @media (max-width: 640px) {
      main {
        padding-inline: 0.75rem;
      }

      .hero,
      .preview,
      .dialog-panel {
        padding: 1rem;
      }

      .preview-meta,
      .dialog-actions {
        align-items: stretch;
      }

      .preview-meta {
        flex-direction: column;
      }

      .dialog-actions button,
      .preview-meta button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --panel: Canvas;
        --panel-elevated: Canvas;
        --border: ButtonBorder;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: LinkText;
        --accent-strong: LinkText;
        --danger: ButtonText;
        --danger-strong: ButtonText;
        --focus: Highlight;
      }

      .hero,
      .preview,
      .dialog,
      button {
        forced-color-adjust: auto;
      }

      .trigger,
      .destructive,
      .secondary,
      .close {
        background: Canvas;
        color: CanvasText;
        border-color: ButtonBorder;
      }

      .skip-link {
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const state = {
      lastTrigger: null,
      deleted: false
    };

    const app = document.getElementById('app');

    function ImagePreviewPage() {
      const imageMarkup = state.deleted
        ? `
          <div class="preview-media" aria-live="polite">
            <div style="aspect-ratio: 16 / 10; display:grid; place-items:center; padding: 2rem; color: var(--muted); text-align: center;">
              Image removed from your library.
            </div>
          </div>
        `
        : `
          <figure class="preview-media">
            <img
              src="data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 800'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop stop-color='%231d2b45'/%3E%3Cstop offset='1' stop-color='%230f1728'/%3E%3C/linearGradient%3E%3CradialGradient id='r' cx='40%25' cy='25%25' r='60%25'%3E%3Cstop stop-color='%238fb4ff' stop-opacity='.85'/%3E%3Cstop offset='1' stop-color='%238fb4ff' stop-opacity='0'/%3E%3C/radialGradient%3E%3C/defs%3E%3Crect width='1280' height='800' fill='url(%23g)'/%3E%3Ccircle cx='460' cy='180' r='220' fill='url(%23r)'/%3E%3Cpath d='M0 640L250 380l170 170 180-220 230 290 160-120 290 140v160H0z' fill='%23283a5d'/%3E%3Cpath d='M130 640l290-300 135 150 110-120 210 270 150-110 255 110v160H130z' fill='%23344a73'/%3E%3Ccircle cx='980' cy='150' r='48' fill='%23ffd88a'/%3E%3C/svg%3E"
              alt="Preview of a landscape image with mountains under a glowing sky">
          </figure>
        `;

      return `
        <main id="main-content">
          <section class="shell" aria-labelledby="page-title">
            <div class="hero">
              <h1 id="page-title">Image Preview</h1>
              <p class="lede">Review the selected image before removing it from your library.</p>

              <div class="preview">
                ${imageMarkup}
                <div class="preview-meta">
                  <div class="details">
                    <strong>Golden Horizon</strong>
                    <span>2048 × 1365 · 4.8 MB</span>
                  </div>
                  <button class="trigger" type="button" data-open-delete-dialog>
                    Delete image
                  </button>
                </div>
              </div>

              <p class="status" id="status" aria-live="polite">${state.deleted ? 'Image deleted from your library.' : ''}</p>
            </div>
          </section>
        </main>
      `;
    }

    function DeleteDialog() {
      return `
        <dialog class="dialog" id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-copy">
          <div class="dialog-panel">
            <div class="dialog-header">
              <div>
                <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
              </div>
              <button class="close" type="button" data-close-dialog aria-label="Close dialog">×</button>
            </div>
            <p class="dialog-body" id="delete-copy">
              This will permanently remove <strong>Golden Horizon</strong> from your library.
            </p>
            <div class="dialog-actions">
              <button class="secondary" type="button" data-close-dialog>Cancel</button>
              <button class="destructive" type="button" data-confirm-delete>Delete</button>
            </div>
          </div>
        </dialog>
      `;
    }

    function App() {
      return `${ImagePreviewPage()}${DeleteDialog()}`;
    }

    function bindEvents() {
      const dialog = document.getElementById('delete-dialog');
      const openButtons = document.querySelectorAll('[data-open-delete-dialog]');
      const closeButtons = dialog.querySelectorAll('[data-close-dialog]');
      const confirmButton = dialog.querySelector('[data-confirm-delete]');
      const status = document.getElementById('status');

      openButtons.forEach((button) => {
        button.addEventListener('click', () => {
          state.lastTrigger = button;
          if (!dialog.open) {
            dialog.showModal();
          }
          const focusTarget = dialog.querySelector('[data-close-dialog]');
          focusTarget.focus();
        });
      });

      closeButtons.forEach((button) => {
        button.addEventListener('click', () => {
          dialog.close();
        });
      });

      confirmButton.addEventListener('click', () => {
        state.deleted = true;
        dialog.close();
        render();
        status.textContent = 'Image deleted from your library.';
      });

      dialog.addEventListener('cancel', () => {
        state.lastTrigger = document.querySelector('[data-open-delete-dialog]');
      });

      dialog.addEventListener('close', () => {
        if (state.lastTrigger && typeof state.lastTrigger.focus === 'function') {
          state.lastTrigger.focus();
        }
      });

      dialog.addEventListener('click', (event) => {
        if (event.target === dialog) {
          dialog.close();
        }
      });
    }

    function render() {
      app.innerHTML = App();
      bindEvents();
    }

    render();
  </script>
</body>
</html>
