 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <div id="app"></div>

   <script>
     const state = {
       lastTrigger: null,
       deleted: false
     };

     const app = document.getElementById('app');

     function ImagePreviewPage() {
       const imageMarkup = state.deleted
         ? `
           <div class="preview-media" aria-live="polite">
             <div style="aspect-ratio: 16 / 10; display:grid; place-items:center; padding: 2rem; color: var(--muted); text-align: center;">
               Image removed from your library.
             </div>
           </div>
         `
         : `
           <figure class="preview-media">
             <img
               src="data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 800'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop stop-color='%231d2b45'/%3E%3Cstop offset='1' stop-color='%230f1728'/%3E%3C/linearGradient%3E%3CradialGradient id='r' cx='40%25' cy='25%25' r='60%25'%3E%3Cstop stop-color='%238fb4ff' stop-opacity='.85'/%3E%3Cstop offset='1' stop-color='%238fb4ff' stop-opacity='0'/%3E%3C/radialGradient%3E%3C/defs%3E%3Crect width='1280' height='800' fill='url(%23g)'/%3E%3Ccircle cx='460' cy='180' r='220' fill='url(%23r)'/%3E%3Cpath d='M0 640L250 380l170 170 180-220 230 290 160-120 290 140v160H0z' fill='%23283a5d'/%3E%3Cpath d='M130 640l290-300 135 150 110-120 210 270 150-110 255 110v160H130z' fill='%23344a73'/%3E%3Ccircle cx='980' cy='150' r='48' fill='%23ffd88a'/%3E%3C/svg%3E"
               alt="Preview of a landscape image with mountains under a glowing sky">
           </figure>
         `;

       return `
         <main id="main-content">
           <section class="shell" aria-labelledby="page-title">
             <div class="hero">
               <h1 id="page-title">Image Preview</h1>
               <p class="lede">Review the selected image before removing it from your library.</p>

               <div class="preview">
                 ${imageMarkup}
                 <div class="preview-meta">
                   <div class="details">
                     <strong>Golden Horizon</strong>
                     <span>2048 × 1365 · 4.8 MB</span>
                   </div>
                   <button class="trigger" type="button" data-open-delete-dialog>
                     Delete image
                   </button>
                 </div>
               </div>

               <p class="status" id="status" aria-live="polite">${state.deleted ? 'Image deleted from your library.' : ''}</p>
             </div>
           </section>
         </main>
       `;
     }

     function DeleteDialog() {
       return `
         <dialog class="dialog" id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-copy">
           <div class="dialog-panel">
             <div class="dialog-header">
               <div>
                 <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
               </div>
               <button class="close" type="button" data-close-dialog aria-label="Close dialog">×</button>
             </div>
             <p class="dialog-body" id="delete-copy">
               This will permanently remove <strong>Golden Horizon</strong> from your library.
             </p>
             <div class="dialog-actions">
               <button class="secondary" type="button" data-close-dialog>Cancel</button>
               <button class="destructive" type="button" data-confirm-delete>Delete</button>
             </div>
           </div>
         </dialog>
       `;
     }

     function App() {
       return `${ImagePreviewPage()}${DeleteDialog()}`;
     }

     function bindEvents() {
       const dialog = document.getElementById('delete-dialog');
       const openButtons = document.querySelectorAll('[data-open-delete-dialog]');
       const closeButtons = dialog.querySelectorAll('[data-close-dialog]');
       const confirmButton = dialog.querySelector('[data-confirm-delete]');
       const status = document.getElementById('status');

       openButtons.forEach((button) => {
         button.addEventListener('click', () => {
           state.lastTrigger = button;
           if (!dialog.open) {
             dialog.showModal();
           }
           const focusTarget = dialog.querySelector('[data-close-dialog]');
           focusTarget.focus();
         });
       });

       closeButtons.forEach((button) => {
         button.addEventListener('click', () => {
           dialog.close();
         });
       });

       confirmButton.addEventListener('click', () => {
         state.deleted = true;
         dialog.close();
         render();
         status.textContent = 'Image deleted from your library.';
       });

       dialog.addEventListener('cancel', () => {
         state.lastTrigger = document.querySelector('[data-open-delete-dialog]');
       });

       dialog.addEventListener('close', () => {
         if (state.lastTrigger && typeof state.lastTrigger.focus === 'function') {
           state.lastTrigger.focus();
         }
       });

       dialog.addEventListener('click', (event) => {
         if (event.target === dialog) {
           dialog.close();
         }
       });
     }

     function render() {
       app.innerHTML = App();
       bindEvents();
     }

     render();
   </script>
 </body>
